func (m *pageMap) getPagesInSection(q pageMapQueryPagesInSection) page.Pages {
	queryPath := q.Path
	queryKeyPart := q.KeyPart
	recursive := q.Recursive
	includeSelf := q.IncludeSelf
	var cacheKeyBuilder strings.Builder
	cacheKeyBuilder.WriteString("gagesInSection")
	cacheKeyBuilder.WriteByte('/')
	cacheKeyBuilder.WriteString(queryPath)
	cacheKeyBuilder.WriteByte('/')
	cacheKeyBuilder.WriteString(queryKeyPart)
	cacheKeyBuilder.WriteByte('/')
	cacheKeyBuilder.WriteString(strconv.FormatBool(recursive))
	cacheKeyBuilder.WriteByte('/')
	cacheKeyBuilder.WriteString(strconv.FormatBool(includeSelf))
	cacheKey := cacheKeyBuilder.String()

	pages, err := m.cachePages.GetOrCreate(cacheKey, func(string) (page.Pages, error) {
		prefix := queryPath
		if !strings.HasSuffix(prefix, "/") {
			prefix += "/"
		}

		var (
			pas         page.Pages
			otherBranch string
		)

		include := q.Include
		pageListed := func(p *pageState) bool {
			if include != nil {
				return include(p)
			}
			formatName := p.m.standaloneOutputFormat.Name
			if formatName != "" {
				return false
			}
			buildCfg := p.m.pageConfig.Build
			listMode := buildCfg.List
			switch listMode {
			case pagemeta.Always:
				return true
			case pagemeta.Never:
				return false
			case pagemeta.ListLocally:
				return true
			default:
				return false
			}
		}

		w := &doctree.NodeShiftTreeWalker[contentNodeI]{
			Tree:     m.treePages,
			Prefix:   prefix,
			LockType: doctree.LockTypeNone,
			Exact:    false,
			NoShift:  false,
		}

		w.Handle = func(key string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
			if recursive {
				if p, ok := n.(*pageState); ok {
					if pageListed(p) {
						pas = append(pas, p)
					}
				}
				return false, nil
			}

			// We store both leafs and branches in the same tree, so for non-recursive walks,
			// we need to walk until the end, but can skip
			// any not belonging to child branches.
			if otherBranch != "" {
				if strings.HasPrefix(key, otherBranch) {
					return false, nil
				}
			}

			if p, ok := n.(*pageState); ok {
				if pageListed(p) {
					pas = append(pas, p)
				}
			}

			isBranch := false
			if ps, ok := n.(*pageState); ok {
				kind := ps.Kind()
				if kind == kinds.KindPage {
					isBranch = false
				} else if kinds.IsBranch(kind) {
					isBranch = true
				} else if ps.isContentNodeBranch() {
					isBranch = true
				}
			} else if n.isContentNodeBranch() {
				isBranch = true
			}
			if isBranch {
				otherBranch = key + "/"
			}

			return false, nil
		}

		err := w.Walk(context.Background())
		if err == nil {
			if includeSelf {
				selfPath := queryPath
				if selfPath == "/" {
					selfPath = ""
				}
				if n := m.treePages.Get(selfPath); n != nil {
					if p, ok := n.(*pageState); ok {
						listed := false
						if include != nil {
							if include(p) {
								listed = true
							}
						} else if p.m.standaloneOutputFormat.Name != "" {
							listed = false
						} else {
							switch p.m.pageConfig.Build.List {
							case pagemeta.Always:
								listed = true
							case pagemeta.Never:
								listed = false
							case pagemeta.ListLocally:
								listed = true
							default:
								listed = false
							}
						}
						if listed {
							pas = append(pas, p)
						}
					}
				}
			}
			page.SortByDefault(pas)
		}

		return pas, err
	})
	if err != nil {
		panic(err)
	}

	return pages
}

